```sql
SELECT DISTINCT T1.Model FROM car_names AS T1 JOIN model_list AS T2 ON T1.MakeId = T2.Make WHERE T1.FullName LIKE 'General% Motors' OR T1.Weight > 3500;
```

SELECT T1.first_name, T1.country_code FROM players AS T1 JOIN (
    SELECT MAX(birth_date) as max_birth_date FROM players
) AS T2 ON T1.birth_date = T2.max_birth_date

```sql
SELECT T2.series_name, T2.Country FROM Cartoon AS T1 JOIN TV_Channel AS T2 ON T1.Channel = T2.id WHERE T1.Directed_by = 'Ben Jones' OR T1.Directed_by = 'Michael Chang';
```

```sql
SELECT T2.Pixel_aspect_ratio_PAR, T2.Country FROM TV_Channel AS T1 JOIN TV_series AS T3 ON T1.id = T3.Channel WHERE T1.Language != 'English' AND T1.Content != 'Cartoon';
```

